import type { Category } from "./types";
import report from "./evaluationReport.json";
import type { Prediction } from "../lib/predictionPolicy";

export type EvaluationResult = {
  testImage: string;
  expectedCategory: Category;
  predictedCategory: Category | null;
  confidence: number;
  failureReason?: string;
};
export type BenchmarkResult = EvaluationResult & {
  sourceLabel: string;
  sourcePath: string;
  sourceUrl: string;
  sha256: string;
  predictions: Prediction[];
  baselineCategory: Category | null;
};

// Measured outputs, generated by npm run evaluate; never substitute invented rows.
export const EVALUATION_IS_PLACEHOLDER = false;
export const evaluationReport = report;
export const evalResults = report.results as BenchmarkResult[];
